// Helper function to find talent by name (case-insensitive, partial match)
export function findTalent(name: string): WikiTalent | undefined {
  const normalizedName = name.toLowerCase().replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, '_');
  
  // Try exact match first
  if (WIKI_TALENTS[normalizedName]) {
    return WIKI_TALENTS[normalizedName];
  }
  
  // Try partial match
  for (const [key, talent] of Object.entries(WIKI_TALENTS)) {
    if (key.includes(normalizedName) || normalizedName.includes(key)) {
      return talent;
    }
    if (talent.name.toLowerCase().includes(name.toLowerCase())) {
      return talent;
    }
  }
  
  return undefined;
}
